use std::{num::NonZeroU16,sync::Arc};
use typst_core::{compiler::{math::layout::MathLayouter,layout::FixedMetrics},entities::{content::{Content,SourceContent},file_id::FileId,span::Span,layout_types::{TextStyle,Pt}}};
fn main(){let body=Content::MathSequence(vec![Content::MathText("a".into()),Content::linebreak(),Content::MathText("b".into())].into());let style=TextStyle::regular(Pt(12.0));let l=MathLayouter::new(&FixedMetrics,true,&style);for(name,b)in[("plain",body.clone()),("source",Content::Source(Arc::new(SourceContent{body,span:Span::from_range(FileId::from_raw(NonZeroU16::new(1).unwrap()),2..5)})))]{let(_,e)=l.layout_equation_measured(&b,&style);println!("{name} lines={} first={} last={} width={} ascent={} descent={}",e.line_count,e.first_baseline,e.last_baseline,e.width,e.ascent,e.descent);}}
